<script setup>
import BusinessPage from '../../components/BusinessPage.vue';
import {reactive,ref} from 'vue';import {api} from '../auth/api.js';import {useCollection} from '../home/useCollection.js';import {LegacyState,LegacyPager} from '../../lib/legacy.js';
const archived=ref(false),state=useCollection('/admin/projects',null,()=>({archived:archived.value})),selected=ref(null),conflict=ref(false);
const blank=()=>({name:'',developer:'',handoverYear:'',scale:'',address:'',latitude:'',longitude:'',amenities:''}),form=reactive(blank());
function fill(m){selected.value=m;const p=m?.project;Object.assign(form,p?{...p,developer:p.developer||'',scale:p.scale||'',address:p.address||'',handoverYear:p.handoverYear??'',latitude:p.latitude??'',longitude:p.longitude??'',amenities:(p.amenities||[]).join('\n')}:blank());conflict.value=false}
async function edit(m){await state.run(async()=>fill(await api('/admin/projects/'+m.project.id)))}
async function reload(){if(!selected.value)return;await edit(selected.value)}
async function save(){await state.run(async()=>{if((form.latitude==='')!==(form.longitude===''))throw Error('Cần cả vĩ độ và kinh độ hoặc để trống cả hai.');const body={name:form.name.trim(),developer:form.developer.trim()||null,handoverYear:form.handoverYear===''?null:Number(form.handoverYear),scale:form.scale.trim()||null,address:form.address.trim()||null,latitude:form.latitude===''?null:Number(form.latitude),longitude:form.longitude===''?null:Number(form.longitude),amenities:form.amenities.split('\n').map(s=>s.trim()).filter(Boolean)};try{const result=await api('/admin/projects'+(selected.value?'/'+selected.value.project.id+'?expectedVersion='+selected.value.contentVersion:''),{method:selected.value?'PATCH':'POST',body});fill(result);state.notice='Đã lưu dự án trên server.';await state.load(state.page)}catch(e){if(e.status===409)conflict.value=true;throw e}})}
async function archive(m){if(!confirm('Lưu trữ mềm dự án này? Các tin liên quan vẫn được giữ.'))return;await state.run(async()=>{try{await api('/admin/projects/'+m.project.id+'?expectedVersion='+m.contentVersion,{method:'DELETE'});if(selected.value?.project.id===m.project.id)fill(null);await state.load(state.page)}catch(e){if(e.status===409)conflict.value=true;throw e}})}
</script><template><BusinessPage title="Quản lý dự án"><label><input v-model="archived" type="checkbox"/> Dự án đã lưu trữ</label><button @click="fill(null)" :disabled="state.busy">Tạo dự án</button><LegacyState :state="state"/><p v-if="conflict" role="alert">Phiên bản đã thay đổi. Tải lại dự án để kiểm tra trước khi lưu tiếp. <button @click="reload" :disabled="state.busy">Tải lại dự án</button></p><p v-if="!state.busy&&!state.items.length">Chưa có dự án phù hợp.</p><section v-for="m in state.items" :key="m.project.id"><h2>{{m.project.name}}</h2><p>{{m.project.address}} · phiên bản {{m.contentVersion}} · {{m.deletedAt?'Đã lưu trữ':'Hoạt động'}}</p><button :disabled="state.busy" @click="edit(m)">Xem / sửa dự án</button><button v-if="!m.deletedAt" :disabled="state.busy" @click="archive(m)">Lưu trữ dự án</button></section><LegacyPager :state="state"/>
<section><h2>{{selected?'Chi tiết dự án':'Dự án mới'}}</h2><form @submit.prevent="save"><fieldset :disabled="state.busy||!!selected?.deletedAt"><label>Tên dự án <input v-model="form.name" required maxlength="255"/></label><label>Chủ đầu tư <input v-model="form.developer" maxlength="255"/></label><label>Năm bàn giao <input v-model="form.handoverYear" type="number" min="1900" max="2200" step="1"/></label><label>Quy mô <textarea v-model="form.scale" maxlength="4000"/></label><label>Địa chỉ <textarea v-model="form.address" maxlength="4000"/></label><label>Vĩ độ đã xác minh <input v-model="form.latitude" type="number" min="-90" max="90" step="any"/></label><label>Kinh độ đã xác minh <input v-model="form.longitude" type="number" min="-179.999999" max="180" step="any"/></label><label>Tiện ích (mỗi dòng một mục, tối đa100) <textarea v-model="form.amenities"/></label><button :disabled="conflict">Lưu dự án</button></fieldset></form></section></BusinessPage></template>
